"""Freeze B2 data-preparation provenance and verify the real training pack.

python -m scripts.v4_heldout.finalize --plan-run preflight_20261016_01 --run-id implementation_20261016_01
"""
import argparse
import json
import platform
import zipfile

import numpy as np
import torch

from .audit import ROOT, sha
from .download import valid_id
from .train_judge import load_pack


def main(plan_run, run_id):
    valid_id(plan_run)
    valid_id(run_id)
    preparation = ROOT / 'reports/v4_heldout_judge' / f'preprocess_{plan_run}'
    pack_path = preparation / 'heldout_train_val_float32.npz'
    data, receipt = load_pack(pack_path)
    assert receipt['preprocess_source_sha256'] == sha(ROOT / 'scripts/v4_heldout/preprocess.py')
    for path, expected in receipt['original_file_sha256'].items():
        assert sha(path) == expected, f'Original input changed: {path}'
    out = ROOT / 'reports/v4_heldout_judge' / run_id
    out.mkdir(parents=True, exist_ok=False)
    sources = sorted((ROOT / 'scripts/v4_heldout').glob('*.py'))
    sources += [ROOT / 'scripts/v4_heldout/README.md', ROOT / 'src/data/preprocess.py', ROOT / 'scripts/v2_quickwins/judge_model.py', ROOT / 'AGENTS.md', ROOT.parent / 'AGENTS.md', ROOT.parent / 'improvements/tasks/02_heldout_judge.md', ROOT.parent / 'improvements/tasks/06_downstream.md']
    manifest = [{'path': str(path.relative_to(ROOT.parent)), 'sha256': sha(path), 'bytes': path.stat().st_size} for path in sources]
    with zipfile.ZipFile(out / 'source_snapshot.zip', 'x', compression=zipfile.ZIP_DEFLATED) as archive:
        for path in sources:
            archive.write(path, path.relative_to(ROOT.parent).as_posix())
    (out / 'source_manifest.json').write_text(json.dumps(manifest, indent=2), encoding='utf-8')
    checks = {'passed': True, 'cohort_training_run': False, 'cloud_job_launched': False, 'pack_sha256': sha(pack_path), 'complete_preprocessing_receipt': True, 'original_split_and_maps_unchanged': True, 'original_103_patients_excluded': True, 'new_train_val_patients_disjoint': True, 'train_patients': len(set(data['train_patient'])), 'val_patients': len(set(data['val_patient'])), 'train_slices': len(data['train_x']), 'val_slices': len(data['val_x']), 'pack_float32_range_and_labels_valid': True, 'pack_contains_original_test_images': False, 'source_snapshot_sha256': sha(out / 'source_snapshot.zip'), 'python': platform.python_version(), 'numpy': np.__version__, 'torch': torch.__version__}
    (out / 'pretraining_checks.json').write_text(json.dumps(checks, indent=2), encoding='utf-8')
    protocol = {'status': 'prepared_not_launched', 'seeds': [0, 1, 2], 'epochs': 40, 'batch_size': 64, 'architecture': 'existing grayscale ResNet-18 acquisition judge', 'optimiser': 'AdamW lr1e-3 weight_decay5e-4 with OneCycleLR', 'primary_augmentation': 'original robust intensity/noise/shift/horizontal-flip recipe plus independent vertical flip p=0.5', 'comparison_augmentation': 'original horizontal-only robust recipe via --legacy-horizontal-only', 'selection': 'earliest maximum mean clean/noise03 new-validation slice balanced accuracy over both heads', 'post_selection_stress_checks': ['vertical flip', 'rotation 180 degrees'], 'selection_or_training_uses_original_test_images': False, 'new_cohort_reserved_for_judge_only': True, 'pack_sha256': checks['pack_sha256'], 'training_core_sha256': sha(ROOT / 'scripts/v4_heldout/train_judge.py'), 'orientation_audit': 'reports/v4_heldout_judge/orientation_20261016_01/', 'cloud_allowance_approved': False}
    (out / 'training_protocol.json').write_text(json.dumps(protocol, indent=2), encoding='utf-8')
    (out / 'README.md').write_text(f'''# B2 implementation and real-pack checks

Generated by `python -m scripts.v4_heldout.finalize --plan-run {plan_run} --run-id {run_id}`. `pretraining_checks.json` records completed real-pack exclusion, patient separation, precision/range, label consistency, hash and original-file preservation checks. `source_manifest.json` and `source_snapshot.zip` preserve all B2 preparation/training-core code, the reused preprocessing/model definitions and applicable instructions. `training_protocol.json` freezes the prepared primary/comparison recipes and post-selection orientation stress checks. This is not a trained-judge result. Visual review of the preprocessing QA sheet is a separate step.

## Completed data stages

- `../{plan_run}/`: audit.py's frozen series/patient plan, original-cohort exclusions, input hashes and B5 clinical-label feasibility manifests.
- `../download_{plan_run}/`: download.py's initial S3 failure receipt and verified partial headers, preserved unchanged.
- `../download_{plan_run}_recovery_01/`: resume_download.py's successful GCS recovery, every DICOM header, prior-file hashes and verified actual byte count.
- `../preprocess_{plan_run}/`: preprocess.py's float32 train/val pack, retained/rejected metadata, cohort counts, preprocessing hashes and visual QA sheet. Images/splits are under `data/processed/ax_t1_128_heldout/{plan_run}/`.
- `../preprocessing_parity_20261016_01/`: in-memory parity check of original training images in all four cells; each exactly matches its saved array.
- `../runner_smoke_20261016_01/`: synthetic CPU augmentation/forward/backward check of the training core; no MRI training or scientific performance estimate.
- `reports/v4_downstream/mask_feasibility_20261016_01/`: audit_masks.py's small official metadata audit; no mask-image download.

## Still required for B2

Package the prepared train_judge.py core in one Modal app with explicit run/volume namespaces and approved compute after B1's active app finishes. Train seeds 0/1/2 for 40 epochs. Following the exploratory header audit, the primary augmentation adds independently sampled vertical flips (p=0.5) to the existing robust horizontal/intensity/noise/shift recipe; --legacy-horizontal-only retains the old recipe as a comparison. Select the earliest best mean clean/noisy validation balanced accuracy across the two heads, then report vertical-flip and 180-degree stress predictions after freezing. Only the 16 new validation patients select checkpoints. Freeze all three checkpoints before testing on the original 934 slices. Report per-head/class/direction and patient-clustered accuracy intervals, then regrade original and B1/B3 counterfactuals/baselines without tuning on their results. Do not promote a poorly discriminating or orientation-sensitive judge as conclusive. No cloud wrapper was launched and no extra compute allowance is implied by the download approval.

Never add these 64 patients to generator training, generator selection or B3 operating-point selection. B2 and B5 remain unchecked on the roadmap; current papers/results are unchanged.
''', encoding='utf-8')
    print(json.dumps(checks, indent=2))


if __name__ == '__main__':
    parser = argparse.ArgumentParser(__doc__)
    parser.add_argument('--plan-run', required=True)
    parser.add_argument('--run-id', required=True)
    args = parser.parse_args()
    main(args.plan_run, args.run_id)
